function initThemeToggle(){const e=document.getElementById("theme-toggle");if(!e)return;if(e.dataset.listenerBound)return;e.dataset.listenerBound="true";const t=t=>{t?(e.innerHTML='\n                <svg class="theme-toggle-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false">\n                    <path d="M12 3v2M12 19v2M5 5l1.5 1.5M17.5 17.5L19 19M3 12h2M19 12h2M5 19l1.5-1.5M17.5 6.5L19 5" />\n                    <circle cx="12" cy="12" r="4.5" />\n                </svg>\n            ',e.setAttribute("title","Toggle Dark Mode"),e.setAttribute("aria-label","Toggle Dark Mode")):(e.innerHTML='\n                <svg class="theme-toggle-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false">\n                    <path d="M21 12.8A8.8 8.8 0 0 1 11.2 3 8.8 8.8 0 1 0 21 12.8Z" fill="currentColor" />\n                </svg>\n            ',e.setAttribute("title","Toggle Light Mode"),e.setAttribute("aria-label","Toggle Light Mode"))};"light"===localStorage.getItem("theme")?(document.body.classList.add("light-theme"),t(!0)):t(!1),e.addEventListener("click",()=>{document.body.classList.toggle("light-theme");const e=document.body.classList.contains("light-theme");t(e);const i=e?"light":"dark";localStorage.setItem("theme",i)})}"undefined"!=typeof window&&(window.initThemeToggle=initThemeToggle);